fn search_insert(xs: &Vec<i32>, target: i32) -> usize {
    let mut left: usize = 0;
    let mut right: usize = xs.len();
    // Invariant: the insertion position k lies in [left, right]
    while left < right {
        // Prevent overflow by computing mid this way
        let mid = left + (right - left) / 2;
        if xs[mid] < target {
            // All indices ≤ mid are too small, drop them
            left = mid + 1;
        } else {
            // xs[mid] ≥ target, so the insertion point is ≤ mid
            right = mid;
        }
    }
    // Now left == right is the smallest index k with xs[k] ≥ target,
    // or k == xs.len() if target is larger than all elements.
    left
}

